package org.strongswan.android.rookstride;
import org.junit.Test;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import javax.net.ssl.*;import java.security.cert.Certificate;import static org.junit.Assert.*;
public final class ArtifactDownloaderTest {
    static final class Reply extends HttpsURLConnection {
        byte[] bytes=PublicArtifactCatalogTest.BYTES;int code=200;String location,encoding;long length=-1;IOException readFailure;boolean disconnected;java.util.concurrent.CountDownLatch headerGate,headerStarted,disconnectGate,disconnectStarted;
        Reply(URL url){super(url);}public void connect(){}public void disconnect(){disconnected=true;if(disconnectStarted!=null)disconnectStarted.countDown();await(disconnectGate);}public boolean usingProxy(){return false;}public String getCipherSuite(){return "fixture";}public Certificate[] getLocalCertificates(){return null;}public Certificate[] getServerCertificates(){return null;}
        static void await(java.util.concurrent.CountDownLatch gate){if(gate!=null)for(;;)try{gate.await();return;}catch(InterruptedException ignored){}}
        public int getResponseCode(){if(headerStarted!=null)headerStarted.countDown();await(headerGate);return code;}public long getContentLengthLong(){return length;}public String getHeaderField(String name){return name.equals("Location")?location:name.equals("Content-Encoding")?encoding:null;}
        public InputStream getInputStream()throws IOException{if(readFailure!=null)throw readFailure;return new ByteArrayInputStream(bytes);}
    }
    static final class Transport implements ArtifactDownloader.Transport {
        final Deque<Object> replies=new ArrayDeque<>();final List<String> requests=new ArrayList<>();Transport next;int fallback;
        public HttpsURLConnection open(URL url)throws IOException{requests.add(url.toExternalForm());Object value=replies.removeFirst();if(value instanceof IOException)throw (IOException)value;return (Reply)value;}
        public ArtifactDownloader.Transport fallback(){fallback++;return next;}
    }
    static File directory()throws Exception{return Files.createTempDirectory("rook-public-").toFile().getCanonicalFile();}
    static Reply reply()throws Exception{return new Reply(new URL("https://github.com/fixture"));}
    private interface Checked{void run()throws Exception;}
    private static void refuses(Checked action)throws Exception{try{action.run();fail("Unverified public bytes were accepted");}catch(IOException expected){}}
    @Test public void streamsVerifiesAndReusesCacheWithoutAnotherHttpRequest()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();Reply r=reply();t.replies.add(r);ArtifactDownloader d=new ArtifactDownloader(c,directory(),t);File result=d.acquire(c.asset("xray","x86_64"));assertArrayEquals(PublicArtifactCatalogTest.BYTES,Files.readAllBytes(result.toPath()));assertEquals(result,d.acquire(c.asset("xray","x86_64")));assertEquals(1,t.requests.size());assertTrue(r.disconnected);}
    @Test public void temporaryOriginFailureTriesPinnedAlternateBeforeNetworkFallback()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();t.replies.add(new UnknownHostException("fixture"));Reply r=reply();t.replies.add(r);new ArtifactDownloader(c,directory(),t).acquire(c.asset("adguard","x86_64"));assertEquals(2,t.requests.size());assertTrue(t.requests.get(1).startsWith("https://api.github.com/"));assertEquals(0,t.fallback);assertEquals("application/octet-stream",r.getRequestProperty("Accept"));}
    @Test public void fixedApiSourceMayRecoverAnOfficialReleaseHttpRefusal()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();Reply denied=reply();denied.code=403;t.replies.add(denied);t.replies.add(reply());new ArtifactDownloader(c,directory(),t).acquire(c.asset("adguard","x86_64"));assertEquals(2,t.requests.size());assertEquals(0,t.fallback);}
    @Test public void finalPermanentHttpRefusalCannotTriggerUnderlayFallback()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();Reply denied=reply();denied.code=404;t.replies.add(denied);refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64")));assertEquals(0,t.fallback);}
    @Test public void fixedPublic403UsesOneExplicitFallbackBut401And410RemainFatal()throws Exception{
        PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport first=new Transport(),next=new Transport();first.next=next;Reply limited=reply();limited.code=403;first.replies.add(limited);next.replies.add(reply());new ArtifactDownloader(c,directory(),first).acquire(c.asset("xray","x86_64"));assertEquals(1,first.requests.size());assertEquals(1,first.fallback);assertEquals(1,next.requests.size());assertEquals(0,next.fallback);
        for(int status:new int[]{401,410}){Transport rejected=new Transport();rejected.next=new Transport();Reply response=reply();response.code=status;rejected.replies.add(response);refuses(()->new ArtifactDownloader(c,directory(),rejected).acquire(c.asset("xray","x86_64")));assertEquals(1,rejected.requests.size());assertEquals(0,rejected.fallback);}
    }
    @Test public void onlyExhaustedTransportUsesExplicitOptionalNetworkFallback()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport(),next=new Transport();t.next=next;t.replies.add(new SocketTimeoutException());next.replies.add(reply());new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64"));assertEquals(1,t.fallback);assertEquals(1,next.requests.size());}
    @Test public void certificateOrHostnameFailureNeverUsesAlternateOrUnderlay()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();for(IOException failure:new IOException[]{new SSLPeerUnverifiedException("hostname"),new SSLHandshakeException("certificate")}){Transport t=new Transport();t.replies.add(failure);refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("adguard","x86_64")));assertEquals(1,t.requests.size());assertEquals(0,t.fallback);}}
    @Test public void typedSslAbruptEndCanTryNextPinnedOriginButCertificateCauseCannot()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();SSLException abrupt=new SSLException("abrupt");abrupt.initCause(new EOFException());t.replies.add(abrupt);t.replies.add(reply());new ArtifactDownloader(c,directory(),t).acquire(c.asset("adguard","x86_64"));assertEquals(2,t.requests.size());Transport bad=new Transport();SSLException certificate=new SSLException("certificate");certificate.initCause(new java.security.cert.CertificateException());bad.replies.add(certificate);refuses(()->new ArtifactDownloader(c,directory(),bad).acquire(c.asset("adguard","x86_64")));assertEquals(0,bad.fallback);}
    @Test public void redirectsKeepTlsAndStayWithinApkHostPolicy()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();Reply r=reply();r.code=302;r.location="https://release-assets.githubusercontent.com/release?token=fixture";t.replies.add(r);Reply ok=reply();t.replies.add(ok);new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64"));assertEquals(2,t.requests.size());assertTrue(r.disconnected);assertFalse(r.getInstanceFollowRedirects());assertFalse(ok.getInstanceFollowRedirects());}
    @Test public void downgradeAndForeignRedirectsStopWithoutFallback()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();for(String target:new String[]{"http://github.com/x","https://private.example/x"}){Transport t=new Transport();Reply r=reply();r.code=302;r.location=target;t.replies.add(r);refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64")));assertEquals(1,t.requests.size());assertEquals(0,t.fallback);}}
    @Test public void redirectLoopIsBounded()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();Transport t=new Transport();for(int i=0;i<4;i++){Reply r=reply();r.code=302;r.location="https://github.com/loop";t.replies.add(r);}refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64")));assertEquals(4,t.requests.size());assertEquals(0,t.fallback);}
    @Test public void checksumAndLengthFailuresNeverPublishOrUseAnotherSource()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();for(int mode=0;mode<3;mode++){Transport t=new Transport();Reply r=reply();r.bytes=mode==0?new byte[PublicArtifactCatalogTest.BYTES.length]:mode==1?new byte[PublicArtifactCatalogTest.BYTES.length+1]:new byte[1];t.replies.add(r);File cache=directory();refuses(()->new ArtifactDownloader(c,cache,t).acquire(c.asset("adguard","x86_64")));assertEquals(0,cache.list().length);assertEquals(0,t.fallback);}}
    @Test public void corruptExistingCacheIsPreservedAndDoesNotTriggerHttpRepair()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();File cache=directory(),bad=new File(cache,c.asset("xray","x86_64").sha256);byte[] old={1,2,3};Files.write(bad.toPath(),old);Transport t=new Transport();refuses(()->new ArtifactDownloader(c,cache,t).acquire(c.asset("xray","x86_64")));assertArrayEquals(old,Files.readAllBytes(bad.toPath()));assertTrue(t.requests.isEmpty());}
    @Test public void symlinkAndInvalidEncodingAreRejected()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();File cache=directory(),outside=File.createTempFile("rook-outside-",".data");Files.write(outside.toPath(),PublicArtifactCatalogTest.BYTES);Files.createSymbolicLink(new File(cache,c.asset("xray","x86_64").sha256).toPath(),outside.toPath());refuses(()->new ArtifactDownloader(c,cache,new Transport()).cached(c.asset("xray","x86_64")));Transport t=new Transport();Reply r=reply();r.encoding="gzip";t.replies.add(r);refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("xray","x86_64")));assertEquals(0,t.fallback);}
    @Test public void trustedAndroidRootAliasIsCanonicalizedButChildLinksRemainForbidden()throws Exception{File parent=directory(),actual=new File(parent,"app-cache"),alias=new File(parent,"android-alias");assertTrue(actual.mkdir());Files.createSymbolicLink(alias.toPath(),actual.toPath());File accepted=ArtifactDownloader.privateCache(alias);assertEquals(new File(actual,"public-components").getCanonicalFile(),accepted);new ArtifactDownloader(PublicArtifactCatalogTest.catalog(),accepted,new Transport());File outside=directory();assertTrue(accepted.delete());Files.createSymbolicLink(accepted.toPath(),outside.toPath());refuses(()->ArtifactDownloader.privateCache(alias));}
    @Test public void callerDeadlineRefusesAnotherWorkerUntilBlockedDnsSettles()throws Exception{
        PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();File cache=directory();java.util.concurrent.CountDownLatch started=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);Reply connection=reply();
        ArtifactDownloader.Transport blocked=url->{started.countDown();for(;;)try{release.await();break;}catch(InterruptedException ignored){}return connection;};
        long before=System.nanoTime();try{refuses(()->new ArtifactDownloader(c,cache,blocked,150).acquire(c.asset("xray","x86_64")));assertTrue(started.await(1,java.util.concurrent.TimeUnit.SECONDS));assertTrue(java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-before)<2500);assertTrue(ArtifactDownloader.downloadBusy());Transport fresh=new Transport();refuses(()->new ArtifactDownloader(c,directory(),fresh).acquire(c.asset("adguard","x86_64")));assertTrue(fresh.requests.isEmpty());}
        finally{release.countDown();long end=System.nanoTime()+2_000_000_000L;while(ArtifactDownloader.downloadBusy()&&System.nanoTime()<end)Thread.sleep(5);}
        assertFalse(ArtifactDownloader.downloadBusy());assertTrue(connection.disconnected);assertEquals(0,cache.list().length);
    }
    @Test public void blockedDisconnectCannotHoldTheDeadlineCallerOrPermitAnotherDownload()throws Exception{
        PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();File cache=directory();Transport t=new Transport();Reply connection=reply();connection.headerGate=new java.util.concurrent.CountDownLatch(1);connection.headerStarted=new java.util.concurrent.CountDownLatch(1);connection.disconnectGate=new java.util.concurrent.CountDownLatch(1);connection.disconnectStarted=new java.util.concurrent.CountDownLatch(1);t.replies.add(connection);
        long before=System.nanoTime();try{refuses(()->new ArtifactDownloader(c,cache,t,150).acquire(c.asset("xray","x86_64")));assertTrue(java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-before)<2500);assertTrue(connection.disconnectStarted.await(1,java.util.concurrent.TimeUnit.SECONDS));assertTrue(ArtifactDownloader.downloadBusy());Transport fresh=new Transport();refuses(()->new ArtifactDownloader(c,directory(),fresh).acquire(c.asset("adguard","x86_64")));assertTrue(fresh.requests.isEmpty());assertEquals(0,cache.list().length);}
        finally{connection.headerGate.countDown();connection.disconnectGate.countDown();long end=System.nanoTime()+2_000_000_000L;while(ArtifactDownloader.downloadBusy()&&System.nanoTime()<end)Thread.sleep(5);}
        assertFalse(ArtifactDownloader.downloadBusy());assertEquals(0,cache.list().length);
    }
    @Test public void peerStreamIsVerifiedAndInterruptionStopsBeforeHttp()throws Exception{PublicArtifactCatalog c=PublicArtifactCatalogTest.catalog();File cache=directory();ArtifactDownloader d=new ArtifactDownloader(c,cache,null);assertNotNull(d.accept(c.asset("xray","x86_64"),()->new ByteArrayInputStream(PublicArtifactCatalogTest.BYTES)));Transport t=new Transport();Thread.currentThread().interrupt();try{refuses(()->new ArtifactDownloader(c,directory(),t).acquire(c.asset("adguard","x86_64")));assertTrue(t.requests.isEmpty());}finally{Thread.interrupted();}}
}
